-- audit_20260924_pack_table_rows_rebases_retail_basis_rows_on_the_live_ask
--
-- known-issues #50 (2026-09-24). pack_table_rows took value_ratio / is_positive_ev / pack_ev /
-- ev_margin_pct straight from mv_pack_ev_latest. For Top Shot rows written by job 71
-- backfill_topshot_historical_pack_ev (price_source NULL) those are measured against the RETAIL price of
-- a sold-out pack. /nba-top-shot/packs sorts by value_ratio_desc by default, so at 3:40 PM PT its top
-- three rows were Got Game S1 Drops 2/3/4 at 6.28x / 5.28x / 3.05x against $9 retail, while the only
-- way to buy them is the secondary market at $250 / $250 / $249 (0.23x / 0.19x / 0.11x).
--
-- Fix: for Top Shot rows whose EV snapshot carries no price_source (the retail basis), rebase the four
-- verdict fields on the row's own live ask (the same expression the view already publishes as
-- secondary_ask), and NULL them where no live ask exists. ev_pack_price becomes that ask. Every other
-- row, and every other collection, is untouched.
--
-- Dry run against live data (3:45 PM PT): 97 rows change, all Top Shot with price_source NULL;
-- 0 rows outside that scope; 6,004 rows before and after; Top Shot +EV rows 32 -> 27.
-- View options: reloptions NULL before and after (no security_invoker to lose); CREATE OR REPLACE
-- keeps the ACL. Column names, order and types are unchanged (ev_pack_price cast to numeric(10,2)).
--
-- Revert: re-apply the pack_table_rows body from 20260924043211.
--
-- definer-view: intentional — pack_table_rows was a definer view before this change (reloptions NULL, on
-- security_definer_view_allowlist since 2026-06-28); CREATE OR REPLACE keeps that mode. This marker line was
-- added to the file AFTER apply (the guard asked for it); the applied statement is otherwise byte-identical.

CREATE OR REPLACE VIEW public.pack_table_rows AS
SELECT pd.dist_id, pd.collection_id, c.name AS collection_name, CASE WHEN ((c.name)::text = 'NBA Top Shot'::text) THEN 'nba-top-shot'::text WHEN ((c.name)::text = 'NFL All Day'::text) THEN 'nfl-all-day'::text WHEN ((c.name)::text = 'LaLiga Golazos'::text) THEN 'laliga-golazos'::text WHEN ((c.name)::text = 'UFC Strike'::text) THEN 'ufc-strike'::text ELSE lower(replace((c.name)::text, ' '::text, '-'::text)) END AS collection_slug, COALESCE(pd.title, (pd.metadata ->> 'name'::text)) AS title, COALESCE((pd.metadata ->> 'thumbnail'::text), pd.image_url) AS image_url, pd.nft_type, lower((pd.metadata ->> 'tier'::text)) AS tier, (pd.metadata ->> 'pack_type'::text) AS pack_type, (pd.metadata ->> 'description'::text) AS description, CASE WHEN ((pd.metadata ->> 'retail_price_usd'::text) IS NULL) THEN NULL::numeric WHEN (((pd.metadata ->> 'retail_price_usd'::text))::numeric >= (1000000)::numeric) THEN round((((pd.metadata ->> 'retail_price_usd'::text))::numeric / (100000000)::numeric), 2) ELSE round(((pd.metadata ->> 'retail_price_usd'::text))::numeric, 2) END AS retail_price_usd, ((pd.metadata ->> 'number_of_pack_slots'::text))::integer AS slots, pd.total_minted, pd.total_opened, pd.total_sealed, COALESCE(NULLIF(pd.depletion_pct, (0)::smallint), CASE WHEN sent.is_sentinel THEN NULL::smallint ELSE (round((pev.depletion_pct)::double precision))::smallint END) AS depletion_pct, ( CASE WHEN sent.is_sentinel THEN NULL::numeric WHEN rb.retail_basis THEN CASE WHEN (rb.live_ask > (0)::numeric) THEN round((pev.gross_ev - rb.live_ask), 2) ELSE NULL::numeric END ELSE pev.pack_ev END)::numeric(10,2) AS pack_ev, ( CASE WHEN sent.is_sentinel THEN NULL::numeric ELSE pev.gross_ev END)::numeric(10,2) AS gross_ev, (CASE WHEN rb.retail_basis THEN rb.live_ask ELSE pev.pack_price END)::numeric(10,2) AS ev_pack_price, ( CASE WHEN sent.is_sentinel THEN NULL::numeric WHEN rb.retail_basis THEN CASE WHEN (rb.live_ask > (0)::numeric) THEN round((pev.gross_ev / rb.live_ask), 4) ELSE NULL::numeric END ELSE pev.value_ratio END)::numeric(12,4) AS value_ratio, CASE WHEN sent.is_sentinel THEN NULL::boolean WHEN rb.retail_basis THEN CASE WHEN (rb.live_ask > (0)::numeric) THEN (pev.gross_ev > rb.live_ask) ELSE NULL::boolean END ELSE pev.is_positive_ev END AS is_positive_ev, CASE WHEN sent.is_sentinel THEN NULL::smallint ELSE pev.fmv_coverage_pct END AS fmv_coverage_pct, pev.edition_count, pev.total_unopened, CASE WHEN sent.is_sentinel THEN NULL::smallint ELSE pev.depletion_pct END AS ev_depletion_pct, pev.snapshotted_at AS ev_snapshotted_at, CASE WHEN sent.is_sentinel THEN NULL::numeric WHEN rb.retail_basis THEN CASE WHEN ((pev.gross_ev IS NOT NULL) AND (rb.live_ask > (0)::numeric)) THEN round((((pev.gross_ev - rb.live_ask) / rb.live_ask) * (100)::numeric), 1) ELSE NULL::numeric END WHEN ((pev.pack_ev IS NOT NULL) AND (pev.pack_price > (0)::numeric)) THEN round(((pev.pack_ev / pev.pack_price) * (100)::numeric), 1) ELSE NULL::numeric END AS ev_margin_pct, pd.first_seen_at, pd.updated_at, CASE WHEN ((pev.edition_count = 1) AND (pev.pack_ev > (500)::numeric)) THEN true ELSE false END AS is_rare_single_pack, pev.primary_price, CASE WHEN (pas.live_ask IS NOT NULL) THEN pas.live_ask WHEN (snap.fresh IS TRUE) THEN NULL::numeric ELSE pev.secondary_ask END AS secondary_ask, pev.price_source, CASE WHEN (pev.primary_available IS NOT NULL) THEN pev.primary_available WHEN ((pd.collection_id = 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid) AND ((pd.metadata ->> 'endTime'::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}'::text) AND ((("substring"((pd.metadata ->> 'endTime'::text), 1, 19))::timestamp without time zone AT TIME ZONE 'UTC'::text) < now())) THEN false WHEN ((pd.collection_id = '06248cc4-b85f-47cd-af67-1855d14acd75'::uuid) AND (pd.metadata ? 'primary_state'::text)) THEN (((pd.metadata ->> 'primary_state'::text) <> 'Complete'::text) AND (((pd.metadata ->> 'primary_available_supply'::text))::integer > 0) AND (((pd.metadata ->> 'primary_start_time'::text))::timestamp with time zone <= now()) AND (((pd.metadata ->> 'primary_end_time'::text))::timestamp with time zone > now())) ELSE NULL::boolean END AS primary_available, CASE WHEN (pas.live_ask IS NOT NULL) THEN true WHEN (snap.fresh IS TRUE) THEN false ELSE pev.secondary_available END AS secondary_available, ( CASE WHEN sent.is_sentinel THEN NULL::numeric ELSE pev.typical_ev END)::numeric(10,2) AS typical_ev, CASE WHEN (pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid) THEN tss.last_success_at WHEN (pd.collection_id = 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid) THEN ads.opened_updated_at ELSE NULL::timestamp with time zone END AS supply_as_of, CASE WHEN (NULLIF(pd.depletion_pct, (0)::smallint) IS NOT NULL) THEN CASE WHEN (pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid) THEN tss.last_success_at WHEN (pd.collection_id = 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid) THEN ads.opened_updated_at ELSE NULL::timestamp with time zone END WHEN ((NOT sent.is_sentinel) AND (pev.depletion_pct IS NOT NULL)) THEN pev.snapshotted_at ELSE NULL::timestamp with time zone END AS depletion_as_of FROM ((((((((pack_distributions pd JOIN collections c ON ((c.id = pd.collection_id))) LEFT JOIN mv_pack_ev_latest pev ON (((pev.dist_id = pd.dist_id) AND (pev.collection_id = pd.collection_id) AND (NOT ((pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid) AND (EXISTS ( SELECT 1 FROM pack_ask_state a WHERE ((a.collection_slug = 'nba-top-shot'::text) AND (a.dist_id = pev.dist_id) AND (a.is_listed IS TRUE) AND (a.lowest_ask > (0)::numeric) AND (pev.gross_ev > ((3)::numeric * a.lowest_ask))))))) AND (EXISTS ( SELECT 1 FROM pack_drop_pool dp WHERE ((dp.collection_id = pd.collection_id) AND (dp.dist_id = pd.dist_id)))) AND ((pev.pack_price IS NULL) OR (pev.pack_price < (9999)::numeric)) AND ((pev.fmv_coverage_pct IS NULL) OR (pev.fmv_coverage_pct >= 25))))) LEFT JOIN LATERAL ( SELECT CASE WHEN ((pas0.is_listed IS TRUE) AND (pas0.lowest_ask > (0)::numeric)) THEN pas0.lowest_ask ELSE NULL::numeric END AS live_ask FROM pack_ask_state pas0 WHERE ((pas0.dist_id = pd.dist_id) AND (((pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid) AND (pas0.collection_slug = 'nba-top-shot'::text)) OR ((pd.collection_id = 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid) AND (pas0.collection_slug = 'nfl-all-day'::text)) OR ((pd.collection_id = '06248cc4-b85f-47cd-af67-1855d14acd75'::uuid) AND (pas0.collection_slug = 'laliga-golazos'::text)))) LIMIT 1) pas ON (true)) LEFT JOIN LATERAL ( SELECT ((pev.gross_ev = (0)::numeric) AND (pev.edition_count = 0)) AS is_sentinel) sent ON (true)) LEFT JOIN topshot_pack_supply tss ON (((tss.dist_id = pd.dist_id) AND (pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid)))) LEFT JOIN allday_pack_supply ads ON (((ads.dist_id = pd.dist_id) AND (pd.collection_id = 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid)))) LEFT JOIN LATERAL ( SELECT (ss.last_ok_at > (now() - '01:00:00'::interval)) AS fresh FROM pack_ask_snapshot_state ss WHERE (ss.collection_slug = CASE pd.collection_id WHEN '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid THEN 'nba-top-shot'::text WHEN 'dee28451-5d62-409e-a1ad-a83f763ac070'::uuid THEN 'nfl-all-day'::text WHEN '06248cc4-b85f-47cd-af67-1855d14acd75'::uuid THEN 'laliga-golazos'::text ELSE NULL::text END)) snap ON (true)) LEFT JOIN LATERAL ( SELECT ((pd.collection_id = '95f28a17-224a-4025-96ad-adf8a4c63bfd'::uuid) AND (pev.dist_id IS NOT NULL) AND (pev.price_source IS NULL)) AS retail_basis, CASE WHEN (pas.live_ask IS NOT NULL) THEN pas.live_ask WHEN (snap.fresh IS TRUE) THEN NULL::numeric ELSE pev.secondary_ask END AS live_ask) rb ON (true));
